custom_css:
/* 玻璃标本室：按指定效果图重建；外链素材，原生操作，正文自然增长。 */
:root {
 --gs-ink:#34434e; --gs-muted:#6d7b85; --gs-u:min(0.10626993vw,1px);
 --gs-root:initial;
 --gs-bg:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/reference/background.webp');
 --gs-leaf:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/reference/specimen.webp');
 --gs-avatar-art:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/avatar-slide.webp');
 --gs-name:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/name-tag.webp');
 --gs-fold:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/reasoning-fold.webp');
 --gs-tray:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/action-tray.webp');
 --gs-top:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/top-lintel.webp');
 --gs-input:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/composer.webp');
 --gs-edge:url('https://raw.githubusercontent.com/Lumi729/wuli-laixin/main/assets/glass-specimen-room/final/message-edge.webp');
}

#bg1 {background-image:var(--gs-bg)!important;background-position:center!important;background-size:cover!important;opacity:1!important;}
#bg2 {background-image:none!important;}
#sheld {top:0!important;height:100dvh!important;max-height:100dvh!important;width:min(100%,941px)!important;max-width:941px!important;background:transparent!important;}
#chat {min-height:0;max-height:none!important;flex:1;backdrop-filter:none!important;background:transparent!important;padding:calc(220 * var(--gs-u)) 0 0!important;overflow-x:hidden!important;}
#chat .mes {position:relative;isolation:isolate;flex-shrink:0;box-sizing:border-box;width:90.33%!important;margin:calc(84 * var(--gs-u)) auto calc(66 * var(--gs-u))!important;padding:calc(284 * var(--gs-u)) calc(82 * var(--gs-u)) calc(70 * var(--gs-u))!important;min-height:0!important;height:auto!important;max-height:none!important;overflow:visible!important;border:0!important;border-radius:calc(36 * var(--gs-u)) calc(48 * var(--gs-u)) calc(68 * var(--gs-u)) calc(40 * var(--gs-u))!important;background:linear-gradient(112deg,#f7fbffdc,#edf2f5c9 48%,#f3f7fad6)!important;box-shadow:inset 0 0 0 2px #ffffff94,0 2px 12px #31445118!important;color:#252b30;backdrop-filter:none!important;font-family:'Noto Serif SC','Songti SC','SimSun',serif;}
#chat .mes::after {content:'';position:absolute;inset:calc(-4 * var(--gs-u));border:calc(48 * var(--gs-u)) solid transparent;border-image:var(--gs-edge) 90 / calc(48 * var(--gs-u)) / 0 stretch;pointer-events:none;z-index:2;}
#chat .mes::before {content:'';position:absolute;top:0;right:0;width:calc(185 * var(--gs-u));height:calc(700 * var(--gs-u));background:var(--gs-leaf) right top/100% 100% no-repeat;opacity:.76;mask-image:linear-gradient(#000 65%,transparent);pointer-events:none;z-index:-1;}
#chat .mes > .mesAvatarWrapper {display:contents!important;}
#chat .mes .mesAvatarWrapper > .avatar {position:absolute!important;top:calc(-114 * var(--gs-u));left:0;width:calc(330 * var(--gs-u))!important;height:calc(358 * var(--gs-u))!important;padding:0!important;overflow:visible!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;z-index:3;}
#chat .mes .mesAvatarWrapper > .avatar img {position:absolute;left:27%;top:10%;width:69%!important;height:86%!important;max-height:none!important;object-fit:cover;border-radius:0!important;}
#chat .mes .mesAvatarWrapper > .avatar::after {content:'';position:absolute;inset:0;background:var(--gs-avatar-art) center/100% 100% no-repeat;pointer-events:none;}
#chat .mes .mesAvatarWrapper > :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) {position:absolute;bottom:calc(24 * var(--gs-u));margin:0!important;font-size:calc(20 * var(--gs-u))!important;line-height:1.4;color:#505b62;}
#chat .mes .mesIDDisplay {left:calc(54 * var(--gs-u));}
#chat .mes .mes_timer {left:calc(145 * var(--gs-u));}
#chat .mes .tokenCounterDisplay {left:calc(220 * var(--gs-u));}
#chat .mes > .mes_block {display:flex!important;flex-direction:column;width:100%!important;min-width:0;margin:0!important;padding:0!important;height:auto!important;max-height:none!important;overflow:visible!important;}
#chat .mes .ch_name {display:contents!important;}
#chat .mes .ch_name > .flex-container:first-child {position:absolute;top:calc(70 * var(--gs-u));left:calc(338 * var(--gs-u));right:calc(130 * var(--gs-u));margin:0!important;min-height:0;z-index:4;}
#chat .mes .name_text {display:inline-block;box-sizing:border-box;min-width:calc(226 * var(--gs-u));max-width:100%;padding:calc(17 * var(--gs-u)) calc(40 * var(--gs-u));background:var(--gs-name) center/100% 100% no-repeat;font-size:calc(32 * var(--gs-u))!important;font-weight:400;color:#272c31!important;line-height:1.3;overflow-wrap:anywhere;}
#chat .mes .timestamp {font-size:calc(12 * var(--gs-u));color:#58656d;}
#chat .mes .mes_text {order:1;min-width:0;width:100%!important;height:auto!important;max-height:none!important;overflow:visible!important;padding:0!important;margin:0!important;font-size:calc(32 * var(--gs-u));line-height:1.85;letter-spacing:.08em;overflow-wrap:anywhere;color:#252b30;}
#chat .mes .mes_text p {margin:0 0 .1em;}
#chat .mes .mes_text pre {max-width:100%;overflow-x:auto;white-space:pre;letter-spacing:normal;}
#chat .mes .mes_text table {display:block;max-width:100%;overflow-x:auto;}
#chat .mes .mes_text img {max-width:100%;height:auto;}
#chat .mes .mes_text blockquote {margin:1em 0;padding:.25em .8em;border-left:2px solid #afc2cb;color:#5e7582;}
#chat .mes :is(.mes_media_wrapper,.mes_file_wrapper,.mes_bias) {order:2;min-width:0;}
#chat .mes .mes_reasoning_details {order:3;position:relative;box-sizing:border-box;width:92%;align-self:center;margin:calc(60 * var(--gs-u)) 0 0!important;padding:calc(23 * var(--gs-u)) calc(60 * var(--gs-u)) calc(30 * var(--gs-u))!important;border:0!important;border-radius:0!important;background:var(--gs-fold) center/100% 100% no-repeat!important;box-shadow:none!important;font-size:calc(28 * var(--gs-u));}
#chat .mes .mes_reasoning_details::after {content:'◇';position:absolute;top:calc(-34 * var(--gs-u));left:-6%;width:112%;height:1px;background:#8f9ba67a;line-height:0;text-align:center;color:#89939c;font-size:calc(16 * var(--gs-u));pointer-events:none;}
#chat .mes .mes_reasoning_summary {position:relative;cursor:pointer;gap:8px;color:#353e45;list-style:none;}
#chat .mes .mes_reasoning_summary::-webkit-details-marker {display:none;}
#chat .mes .mes_reasoning_header {padding:0;background:transparent!important;color:inherit;}
#chat .mes .mes_reasoning_header_title {letter-spacing:.12em;}
#chat .mes .mes_reasoning {position:relative;padding:calc(19 * var(--gs-u)) 0 0;margin-top:calc(10 * var(--gs-u));border-top:1px solid #a8b3bd70;color:#424b52;line-height:1.7;overflow-wrap:anywhere;}
#chat .mes .mes_reasoning p {margin:0;}
#chat .mes .mes_buttons {order:4;display:flex;flex:none;justify-content:flex-start;align-self:stretch;align-items:center;flex-wrap:wrap;gap:calc(30 * var(--gs-u));box-sizing:border-box;margin:calc(20 * var(--gs-u)) 0 0!important;padding:calc(18 * var(--gs-u)) calc(42 * var(--gs-u))!important;min-height:calc(98 * var(--gs-u));background:var(--gs-tray) center/100% 100% no-repeat!important;border:0!important;box-shadow:none!important;opacity:1!important;}
#chat .mes .mes_buttons > .mes_button {box-sizing:border-box;width:calc(62 * var(--gs-u));height:calc(62 * var(--gs-u));line-height:calc(62 * var(--gs-u));text-align:center;font-size:calc(30 * var(--gs-u))!important;border:1px solid #fff;border-radius:50%;background:linear-gradient(130deg,#ffffff85,#e5edf33d);box-shadow:0 0 0 2px #72808b4a,inset 0 0 0 2px #ffffff70;color:#303c44!important;filter:none!important;text-shadow:none!important;}
#chat .mes .extraMesButtons {flex-wrap:wrap;gap:10px;color:#526c7c;}
#chat .mes .mes_edit_buttons {order:5;flex-wrap:wrap;}
#chat .mes :is(.mes_edit_textarea,.reasoning_edit_textarea) {background:#f7fbfd;color:#344854;border:1px solid #b6cbd5;}
#chat .mes[is_user="true"] {width:57.4%!important;margin:0 4.78% 0 auto!important;padding:calc(85 * var(--gs-u)) calc(235 * var(--gs-u)) calc(42 * var(--gs-u)) calc(54 * var(--gs-u))!important;min-height:calc(175 * var(--gs-u))!important;}
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar {top:calc(-50 * var(--gs-u));left:auto;right:calc(-8 * var(--gs-u));width:calc(220 * var(--gs-u))!important;height:calc(245 * var(--gs-u))!important;transform:scaleX(-1);}
#chat .mes[is_user="true"] .mesAvatarWrapper > .avatar img {transform:scaleX(-1);}
#chat .mes[is_user="true"] .ch_name > .flex-container:first-child {top:0;left:auto;right:calc(212 * var(--gs-u));}
#chat .mes[is_user="true"] .name_text {min-width:calc(106 * var(--gs-u));padding:calc(10 * var(--gs-u)) calc(27 * var(--gs-u));font-size:calc(28 * var(--gs-u))!important;}
#chat .mes[is_user="true"]::before {display:none;}
#chat .mes[is_user="true"] .mes_buttons {min-height:0;background:none!important;padding:0!important;margin-top:8px!important;gap:10px;}
#chat .mes[is_user="true"] .mes_buttons > .mes_button {width:22px;height:22px;line-height:22px;font-size:12px!important;}
#chat .mes[is_user="true"] .mesAvatarWrapper > :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) {bottom:4px;font-size:10px!important;}
#chat .mes[is_system="true"] {padding-top:calc(160 * var(--gs-u))!important;}
#top-bar {top:calc(35 * var(--gs-u))!important;width:min(94%,886px)!important;height:calc(86 * var(--gs-u))!important;left:50%!important;right:auto!important;margin:0!important;transform:translateX(-50%);border:0!important;background:var(--gs-top) center/100% 100% no-repeat!important;box-shadow:none!important;backdrop-filter:none!important;}
#top-settings-holder {position:absolute!important;top:calc(35 * var(--gs-u))!important;left:50%!important;transform:translateX(-50%);width:min(94%,886px)!important;height:calc(86 * var(--gs-u))!important;padding:0 3%!important;gap:0;justify-content:space-between;background:transparent!important;}
#top-settings-holder::after {content:'玻璃标本室';position:absolute;left:34%;width:32%;top:50%;transform:translateY(-50%);text-align:center;font-family:'Noto Serif SC','Songti SC',serif;font-size:calc(34 * var(--gs-u));letter-spacing:.15em;color:#252c33;pointer-events:none;}
#top-settings-holder > .drawer {width:auto!important;min-width:0!important;flex:0 1 auto;}
#top-settings-holder > .drawer:nth-child(5) {margin-left:34%;}
#top-settings-holder .drawer-icon {font-size:calc(27 * var(--gs-u))!important;width:calc(38 * var(--gs-u))!important;min-width:0!important;background:transparent!important;color:#34434c!important;text-shadow:none!important;filter:none!important;opacity:1!important;}
#send_form {position:relative;isolation:isolate;box-sizing:border-box;width:94%!important;min-height:calc(130 * var(--gs-u));margin:calc(20 * var(--gs-u)) auto calc(55 * var(--gs-u))!important;padding:calc(20 * var(--gs-u)) calc(32 * var(--gs-u))!important;gap:calc(22 * var(--gs-u));border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;}
#send_form::before {content:'';position:absolute;left:0;right:0;bottom:0;height:calc(240 * var(--gs-u));background:var(--gs-input) center bottom/100% 100% no-repeat;z-index:-1;pointer-events:none;}
#send_textarea {background:transparent!important;border:0!important;border-bottom:1px solid #66717c75!important;border-radius:0!important;color:#303d47!important;font-family:'Noto Serif SC','Songti SC',serif;font-size:calc(27 * var(--gs-u))!important;line-height:1.7;padding:calc(8 * var(--gs-u))!important;}
#send_textarea::placeholder {color:#56636d;}
#send_form :is(#send_but,#options_button,#extensionsMenuButton) {font-size:calc(38 * var(--gs-u))!important;color:#303e49!important;text-shadow:none!important;filter:none!important;}
@media(max-width:500px){#chat .mes .mes_text{font-size:max(14px,calc(32 * var(--gs-u)));}#chat .mes .mes_reasoning_details{font-size:max(12px,calc(28 * var(--gs-u)));}#top-settings-holder .drawer-icon{font-size:max(13px,calc(27 * var(--gs-u)))!important;}#chat .mes .timestamp{font-size:8px;}#send_textarea{font-size:14px!important;}}

/* 原生输入栏含扩展按钮容器，保留其事件与自动增高。 */
#form_sheld {flex-shrink:0;}
#nonQRFormItems {align-items:center;column-gap:calc(25 * var(--gs-u));}
#leftSendForm,#rightSendForm {min-width:calc(60 * var(--gs-u));justify-content:center;align-items:center;}
#send_textarea {min-height:calc(60 * var(--gs-u));max-height:35dvh;}
#chat .mes .swipe_left {left:calc(20 * var(--gs-u));bottom:calc(24 * var(--gs-u));}
#chat .mes .swipeRightBlock {position:absolute;right:calc(24 * var(--gs-u));bottom:calc(20 * var(--gs-u));}

#chat .mes[is_user="true"] .mes_buttons {position:absolute;left:calc(54 * var(--gs-u));bottom:calc(8 * var(--gs-u));max-width:45%;opacity:0!important;}
#chat .mes[is_user="true"]:is(:hover,:focus-within) .mes_buttons {opacity:1!important;}
@media(hover:none){#chat .mes[is_user="true"] .mes_buttons{opacity:.65!important;}}
